export function parseTransformDraft(draft: TransformDraft): LayerTransform | null {
  const transform = {
    a: Number(draft.a),
    b: Number(draft.b),
    c: Number(draft.c),
    d: Number(draft.d),
    e: Number(draft.e),
    f: Number(draft.f),
  };
  const determinant = transform.a * transform.d - transform.b * transform.c;
